    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount <= address(this).balance);

        uint256 bBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 rBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 dBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        bool finishedBefore = c.distributionFinished(); if (__ESBMC_reverted()) return;
        uint256 vBefore = c.value(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 bAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 rAfter = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 dAfter = c.totalDistributed(); if (__ESBMC_reverted()) return;

        assert(reverted || (bAfter - bBefore == (vBefore < rBefore ? vBefore : rBefore) && rBefore - rAfter == (vBefore < rBefore ? vBefore : rBefore) && dAfter - dBefore == (vBefore < rBefore ? vBefore : rBefore)));
    }

    receive() external payable {}
}

